function Blob($spec){$p.StandardInput.WriteLine($spec);$p.StandardInput.Flush();$h=[Text.StringBuilder]::new();while(($b=$stream.ReadByte()) -ne 10){if($b -lt 0){throw 'EOF header'};[void]$h.Append([char]$b)};if($h.ToString() -notmatch '^([a-f0-9]{40}) blob ([0-9]+)$'){throw 'Unexpected blob'};$data=[byte[]]::new([int]$Matches[2]);$pos=0;while($pos -lt $data.Length){$n=$stream.Read($data,$pos,$data.Length-$pos);if($n -le 0){throw 'EOF blob'};$pos+=$n};if($stream.ReadByte() -ne 10){throw 'separator'};return ,$data}
